-- Lan–tangi–enjing Absalom lan–jumeneng wonten–ing– sisih margi sang–gapura Lan–dados saben– sang–tiyang ingkang– piyambakipun–dados– dhateng–piyambakipun– prakawis kangge–rawuh dhateng– sang–Raja kangge–pangadilan lan–nimbali Absalom dhateng–piyambakipun lan–ngandika saking–pundi– punika kitha panjenengan Lan–ngandika saking–satunggal taler–taler– Israel abdi–panjenengan

BEGIN;
-- 1001500201: וְהִשְׁכִּים֙ (H7925) → "Lan–tangi–enjing" [opus-4.5-chirho]
WITH np AS (
  INSERT INTO phrase (language_id, created_at)
  SELECT (SELECT id FROM language WHERE code = 'jav'), NOW()
  WHERE NOT EXISTS (
    SELECT 1 FROM phrase p JOIN phrase_word pw ON pw.phrase_id = p.id
    WHERE pw.word_id = '1001500201' AND p.language_id = (SELECT id FROM language WHERE code = 'jav') AND p.deleted_at IS NULL
  )
  RETURNING id
)
INSERT INTO phrase_word (phrase_id, word_id) SELECT id, '1001500201' FROM np ON CONFLICT DO NOTHING;
INSERT INTO gloss (phrase_id, gloss, state, updated_at, source)
SELECT p.id, 'Lan–tangi–enjing', 'UNAPPROVED', NOW(), 'IMPORT'
FROM phrase p JOIN phrase_word pw ON pw.phrase_id = p.id
WHERE pw.word_id = '1001500201' AND p.language_id = (SELECT id FROM language WHERE code = 'jav') AND p.deleted_at IS NULL
ON CONFLICT (phrase_id) DO UPDATE SET gloss = EXCLUDED.gloss, updated_at = EXCLUDED.updated_at, source = EXCLUDED.source;
